import assert from 'node:assert/strict';
import {test} from 'node:test';
import {existsSync} from 'node:fs';
import {AuthFailure} from '../../../apps/server/modules/access/repository.ts';
// 첫 검수 단위: lease만 메모리이며 counter는 실제 authenticated/SQL transaction 접점을 요구한다.
async function api(file:'catalog'|'store',...names:string[]):Promise<Record<string,any>>{const u=new URL('../../../apps/server/modules/backups/installation-resource-'+file+'.ts',import.meta.url),m:Record<string,any>=existsSync(u)?await import(u.href):{};for(const n of names)assert.equal(typeof m[n],'function','FN16 저장 접점 부재: '+n);return m;}
const pid='11111111-1111-4111-8111-111111111111',actorId='22222222-2222-4222-8222-222222222222',clientId='33333333-3333-4333-8333-333333333333',sessionId='44444444-4444-4444-8444-444444444444',keyId='55555555-5555-4555-8555-555555555555';
const resourceRef={id:keyId,version:1,contentHash:'a'.repeat(64)},scope={projectId:pid,actorId,clientId,sessionId,controlGeneration:1};
const exact=(code:string,status:number)=>(e:any)=>e instanceof AuthFailure&&e.message===code&&e.statusCode===status;
function registry(Model:any){let now=Date.parse('2026-10-28T08:00:00.000Z'),sequence=0;const timers=new Map<number,{at:number;run:()=>void}>();const value=new Model({now:()=>now,setTimer:(run:()=>void,delay:number)=>{assert(Number.isFinite(delay)&&delay>=0);const id=++sequence;timers.set(id,{at:now+delay,run});return id;},clearTimer:(id:number)=>{timers.delete(id);}});return{value,timers,now:()=>now,advance(ms:number){now+=ms;for(const [id,t]of [...timers])if(t.at<=now){timers.delete(id);t.run();}}};}
function open(r:ReturnType<typeof registry>,expectedGeneration=0,deadline=r.now()+600000){const ticket=r.value.begin(scope),key=Buffer.alloc(32,0x22);const lease=r.value.activate(ticket,{resourceRef,expectedGeneration,key,deadline});return{ticket,key,lease};}

test('catalog 기본값은 미구성이며 슬롯조회[]·실등록probe0·외부path비노출이다',async()=>{const m=await api('catalog','InstallationResourceCatalog'),catalog=new m.InstallationResourceCatalog();for(const kind of ['TARGET','ENCRYPTION_KEY']){assert.deepEqual(await catalog.list(kind),{state:'UNCONFIGURED',items:[]});await assert.rejects(catalog.prepareSlot('66666666-6666-4666-8666-666666666666',kind),exact('RESOURCE_UNVERIFIED',412));}assert(!JSON.stringify(catalog).includes('absoluteRoot'));});

test('safe handle adapter 없는 catalog 항목은 VERIFIED로 승격되거나 파일probe를 시작하지 않는다',async()=>{const m=await api('catalog','InstallationResourceCatalog');const catalog=new m.InstallationResourceCatalog({installationId:'77777777-7777-4777-8777-777777777777',entries:[{slotId:'66666666-6666-4666-8666-666666666666',displayName:'합성 슬롯',purpose:'KEY_VAULT',absoluteRoot:'/synthetic/not-opened/vault',expectedRootIdentity:{device:'1',inode:'2'},capacityBytes:1048576,profileVersion:1}]});const list=await catalog.list('ENCRYPTION_KEY');assert.notEqual(list.state,'VERIFIED');assert(!JSON.stringify(list).includes('/synthetic/'));await assert.rejects(catalog.prepareSlot('66666666-6666-4666-8666-666666666666','ENCRYPTION_KEY'),exact('RESOURCE_UNVERIFIED',412));});

test('lease는5분상한·단일project와exact actor/client/session/ref·generation에만귀속된다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const x=open(r);assert.equal(x.lease.leaseGeneration,1);const state=r.value.status(scope,resourceRef);assert.equal(state.state,'UNLOCKED');assert.equal(Date.parse(state.unlockedUntil),r.now()+300000);for(const foreign of [{...scope,actorId:'88888888-8888-4888-8888-888888888888'},{...scope,clientId:'88888888-8888-4888-8888-888888888888'},{...scope,sessionId:'88888888-8888-4888-8888-888888888888'}])assert.throws(()=>r.value.status(foreign,resourceRef),exact('NOT_FOUND',404));const other=r.value.begin(scope),second=Buffer.alloc(32,0x33);assert.throws(()=>r.value.activate(other,{resourceRef:{...resourceRef,id:'99999999-9999-4999-8999-999999999999'},expectedGeneration:0,key:second,deadline:r.now()+60000}),exact('RESOURCE_LIMIT',429));assert(second.every(v=>v===0));assert(!JSON.stringify(state).includes('key'));assert(!Object.values(state).some(Buffer.isBuffer));}finally{r.value.dispose();assert.equal(r.timers.size,0);}});

test('로그아웃session·actor·project epoch무효화는진행중KDF ticket의늦은activation과복사ticket을거절한다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry');for(const kind of ['session','actor','project']){const r=registry(m.InstallationKeyLeaseRegistry);try{const ticket=r.value.begin(scope);if(kind==='session')r.value.invalidateSession(sessionId);if(kind==='actor')r.value.invalidateActor(actorId);if(kind==='project')r.value.invalidateProject(pid);const key=Buffer.alloc(32,0x44);assert.throws(()=>r.value.activate(ticket,{resourceRef,expectedGeneration:0,key,deadline:r.now()+60000}),exact('RESOURCE_STATE_UNKNOWN',503));assert(key.every(v=>v===0));const current=r.value.begin(scope),copied={...current},foreignKey=Buffer.alloc(32,0x55);assert.throws(()=>r.value.activate(copied,{resourceRef,expectedGeneration:0,key:foreignKey,deadline:r.now()+60000}),exact('RESOURCE_STATE_UNKNOWN',503));assert(foreignKey.every(v=>v===0));}finally{r.value.dispose();}}});

test('만료timer·logout은DB감사성공과무관하게owned key를소거하고재시작은LOCKED다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry');for(const cause of ['timer','logout']){const r=registry(m.InstallationKeyLeaseRegistry);try{const x=open(r,0,r.now()+1000);if(cause==='timer')r.advance(1000);else r.value.invalidateSession(sessionId);assert(x.key.every(v=>v===0));assert.equal(r.value.status(scope,resourceRef).state,'LOCKED');assert.equal(r.timers.size,0);}finally{r.value.dispose();}}const restarted=registry(m.InstallationKeyLeaseRegistry);try{assert.equal(restarted.value.status(scope,resourceRef).state,'LOCKED');}finally{restarted.value.dispose();}});

test('relock은자기exact generation사용차단을먼저하고DB실패에도LOCKED/auditUNKNOWN을보존한다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const x=open(r);let writes=0;const result=await r.value.relock(scope,resourceRef,1,async()=>{writes++;assert(x.key.every(v=>v===0));assert.equal(r.value.status(scope,resourceRef).state,'LOCKED');throw Error('synthetic-db-failure');});assert.equal(writes,1);assert.equal(result.state,'LOCKED');assert.equal(result.auditState,'UNKNOWN');assert.equal(result.leaseGeneration,2);const next=open(r,2,r.now()+60000);assert.equal(next.lease.leaseGeneration,3);await assert.rejects(r.value.relock(scope,resourceRef,1,async()=>{writes++;}),exact('RESOURCE_VERSION_CONFLICT',409));assert.equal(writes,1);assert.equal(r.value.status(scope,resourceRef).state,'UNLOCKED');assert(next.key.some(v=>v!==0));}finally{r.value.dispose();}});

type Bucket={project_id:string;bucket_kind:string;bucket_key:string;failures:number;window_started_at:Date;blocked_until:Date|null};
function counterFixture(){
 const buckets=new Map<string,Bucket>(),attempts=new Map<string,any>(),unexpected:string[]=[],events:string[]=[];
 let now=Date.parse('2026-10-28T08:00:00.000Z'),authActor=actorId,authFailure=false,storageFailure=false,transactions=0,readDelay=0,depth=0,commitLoss:'before'|'after'|null=null,admitCommitLoss:'before'|'after'|null=null,snapshot:any=null;
 const capture=()=>structuredClone({buckets:[...buckets],attempts:[...attempts]});
 const restore=(v:any)=>{buckets.clear();attempts.clear();for(const [k,row]of v.buckets)buckets.set(k,row);for(const [k,row]of v.attempts)attempts.set(k,row);};
 const boundRow=(sql:string,args:any[])=>{const columns=sql.slice(sql.indexOf('(')+1,sql.indexOf(')')).split(',').map(x=>x.trim()),values=sql.match(/VALUES\s*\(([^)]+)\)/)?.[1]?.split(',').map(x=>x.trim());assert(values&&columns.length===values.length);const row:any={};columns.forEach((name,i)=>{const p=/^\$(\d+)$/.exec(values[i]!);assert(p,'SQL explicit bound values');row[name]=args[Number(p[1])-1];});return row;};
 const db={async query(sql:string,args:any[]=[]){const s=sql.replace(/\s+/g,' ').trim();
  if(s==='BEGIN'){assert.equal(depth,0,'재authenticated 자기교착 금지');transactions++;snapshot=capture();events.push('BEGIN');return{rows:[]};}
  if(s==='COMMIT'){const loss=commitLoss;commitLoss=null;if(loss==='before')throw Error('synthetic-commit-before');snapshot=null;events.push('COMMIT');if(loss==='after')throw Error('synthetic-commit-after');return{rows:[]};}
  if(s==='ROLLBACK'){if(snapshot)restore(snapshot);snapshot=null;events.push('ROLLBACK');return{rows:[]};}
  if(s.startsWith("SELECT set_config('anvil.actor_id'")){assert.equal(args.length,2);assert.equal(args[1],clientId);events.push('GUC');return{rows:[]};}
  if(s==='SELECT clock_timestamp() AS at'){events.push('CLOCK');return{rows:[{at:new Date(now)}]};}
  if(s.startsWith('SELECT p.id,p.archived_at,m.participation FROM anvil.projects p JOIN anvil.project_members m ')){assert.deepEqual(args,[pid,authActor]);return{rows:[{id:pid,archived_at:null,participation:'OWNER'}]};}
  if(s==='SELECT id FROM anvil.projects WHERE id=$1 FOR UPDATE'){assert.deepEqual(args,[pid]);return{rows:[{id:pid}]};}
  if(s.startsWith('SELECT * FROM anvil.installation_key_failure_limits WHERE project_id=$1')&&s.endsWith('FOR UPDATE')){assert.equal(args[0],pid);if(storageFailure)throw Error('synthetic-limit-storage-failure');events.push('READ_LIMIT');now+=readDelay;readDelay=0;return{rows:[...buckets.values()].filter(r=>r.project_id===args[0]).map(r=>structuredClone(r))};}
  if(s.startsWith('INSERT INTO anvil.installation_key_failure_limits(')){if(storageFailure)throw Error('synthetic-limit-storage-failure');const row=boundRow(s,args);assert.equal(row.project_id,pid);assert(['ACTOR_KEY','PROJECT'].includes(row.bucket_kind));assert(Number.isSafeInteger(row.failures)&&row.failures>=1);assert(row.window_started_at instanceof Date);assert(row.blocked_until===null||row.blocked_until instanceof Date);buckets.set(row.bucket_kind+':'+row.bucket_key,structuredClone(row));events.push('WRITE_LIMIT');return{rows:[],rowCount:1};}
  if(s.startsWith('SELECT * FROM anvil.installation_key_attempts WHERE project_id=$1')&&s.endsWith('FOR UPDATE')){assert.equal(args[0],pid);const rows=[...attempts.values()].filter(r=>r.project_id===args[0]&&(args.length===1||r.id===args[1]));return{rows:structuredClone(rows)};}
  if(s.startsWith('INSERT INTO anvil.installation_key_attempts(')){const row=boundRow(s,args);assert.equal(row.project_id,pid);assert.equal(row.actor_id,authActor);assert.equal(row.client_id,clientId);assert.equal(row.session_id,sessionId);assert.equal(row.state,'RESERVED');assert.equal(row.outcome,null);assert(row.created_at instanceof Date);assert(!attempts.has(row.id));attempts.set(row.id,structuredClone(row));events.push('RESERVE');return{rows:[],rowCount:1};}
  if(s==='UPDATE anvil.installation_key_attempts SET state=$3,outcome=$4 WHERE project_id=$1 AND id=$2 AND state=$5'){const row=attempts.get(args[1]);if(!row||row.project_id!==args[0]||row.state!==args[4])return{rows:[],rowCount:0};row.state=args[2];row.outcome=args[3];events.push('ATTEMPT_'+args[2]);return{rows:[],rowCount:1};}
  unexpected.push(s);throw Error('UNEXPECTED_LIMIT_SQL:'+s.slice(0,80));
 }};
 const access={pool:{async connect(){assert.equal(depth,0,'열린 authenticated 안에서 pool transaction 금지');return{query:db.query,release(){}};}},async authenticated(token:string,csrf:null,body:Function){assert.equal(token,'t'.repeat(43));assert.equal(csrf,null);if(authFailure)throw new AuthFailure('AUTH_REQUIRED',401);transactions++;const saved=capture();let committed=false;depth++;events.push('BEGIN');try{const out=await body(db,{actorId:authActor,clientId,serverOwner:false,credentialGeneration:1,reauthUntil:null,authSession:{id:sessionId,idleExpiresAt:new Date(now+3600000).toISOString(),absoluteExpiresAt:new Date(now+3600000).toISOString()}});const loss=admitCommitLoss;admitCommitLoss=null;if(loss==='before')throw Error('synthetic-reserve-commit-before');committed=true;events.push('COMMIT');if(loss==='after')throw Error('synthetic-reserve-commit-after');return out;}catch(e){if(!committed)restore(saved);events.push('ROLLBACK');throw e;}finally{depth--;}}};
 return{access,buckets,attempts,events,unexpected,actor:(a:string)=>{authActor=a;},authFail:()=>{authFailure=true;},authRecover:()=>{authFailure=false;},storageFail:()=>{storageFailure=true;},storageRecover:()=>{storageFailure=false;},advance:(ms:number)=>{now+=ms;},transactions:()=>transactions,now:()=>now,delayRead:(ms:number)=>{readDelay=ms;},loseCommit:(mode:'before'|'after')=>{commitLoss=mode;},loseAdmitCommit:(mode:'before'|'after')=>{admitCommitLoss=mode;}};
}
test('실패5회는별도SQL transaction에남아재시작·상위작업실패에도15분차단을유지한다',async()=>{const m=await api('store','InstallationResourceFailureLimiter'),f=counterFixture(),a=new m.InstallationResourceFailureLimiter(f.access);for(let i=0;i<5;i++){const ticket=await a.admit('t'.repeat(43),pid,keyId);try{await a.recordFailure(ticket);throw Error('synthetic-outer-operation-rollback');}catch(e){assert.equal((e as Error).message,'synthetic-outer-operation-rollback');}}assert.equal(f.buckets.size,2);assert(f.events.includes('GUC'));assert(f.events.includes('WRITE_LIMIT'));const restarted=new m.InstallationResourceFailureLimiter(f.access);await assert.rejects(restarted.admit('t'.repeat(43),pid,keyId),exact('RESOURCE_LIMIT',429));assert.equal(f.transactions(),16);assert.deepEqual(f.unexpected,[]);f.advance(900000);await restarted.admit('t'.repeat(43),pid,keyId);});

test('project 전체실패한도는actor/key분산으로우회하지못하고성공조회가counter를초기화하지않는다',async()=>{const m=await api('store','InstallationResourceFailureLimiter'),f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access);for(let i=0;i<5;i++){f.actor(i%2===0?actorId:'88888888-8888-4888-8888-888888888888');const ticket=await limiter.admit('t'.repeat(43),pid,i%2===0?keyId:'99999999-9999-4999-8999-999999999999');await limiter.recordFailure(ticket);}f.actor('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');await assert.rejects(limiter.admit('t'.repeat(43),pid,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),exact('RESOURCE_LIMIT',429));assert.equal([...f.buckets.values()].filter(v=>v.bucket_kind==='PROJECT')[0]!.failures,5);assert.deepEqual(f.unexpected,[]);});

test('제한기록DB불명/인증실패는KDF후속0이며타인신원을요청필드로받지않는다',async()=>{const m=await api('store','InstallationResourceFailureLimiter');for(const fail of ['storage','auth']){const f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access);if(fail==='storage')f.storageFail();else f.authFail();let kdfCalls=0;await assert.rejects((async()=>{await limiter.admit('t'.repeat(43),pid,keyId);kdfCalls++;})(),exact(fail==='storage'?'RESOURCE_STATE_UNKNOWN':'AUTH_REQUIRED',fail==='storage'?503:401));assert.equal(kdfCalls,0);assert.equal(f.buckets.size,0);assert.deepEqual(f.unexpected,[]);}});

test('활성exact generation의타actor/client/session relock은감사0·원key미소거·UNLOCKED유지다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const x=open(r);let writes=0;for(const field of ['actorId','clientId','sessionId']){const foreign={...scope,[field]:'88888888-8888-4888-8888-888888888888'};await assert.rejects(r.value.relock(foreign,resourceRef,1,async()=>{writes++;}),exact('NOT_FOUND',404));assert.equal(writes,0);assert(x.key.some(v=>v!==0));assert.equal(r.value.status(scope,resourceRef).state,'UNLOCKED');assert.equal(r.value.status(scope,resourceRef).leaseGeneration,1);}}finally{r.value.dispose();}});

test('counter행lock대기뒤session만료는최종clock으로거절하고실패기록write/KDF후속0이다',async()=>{const m=await api('store','InstallationResourceFailureLimiter'),f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access);f.delayRead(3600001);await assert.rejects(limiter.admit('t'.repeat(43),pid,keyId),exact('AUTH_REQUIRED',401));assert.equal(f.buckets.size,0);assert.equal(f.events.includes('WRITE_LIMIT'),false);assert(f.events.indexOf('READ_LIMIT')<f.events.indexOf('CLOCK'));assert.deepEqual(f.unexpected,[]);});

test('로그아웃으로잠긴옛소유이력은새정상session의exactgeneration재해제를영구404로막지않는다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const old=open(r);r.value.invalidateSession(sessionId);assert(old.key.every(v=>v===0));const locked=r.value.status(scope,resourceRef);assert.equal(locked.leaseGeneration,2);const fresh={...scope,sessionId:'99999999-9999-4999-8999-999999999999'},ticket=r.value.begin(fresh),key=Buffer.alloc(32,0x66);const next=r.value.activate(ticket,{resourceRef,expectedGeneration:2,key,deadline:r.now()+60000});assert.equal(next.leaseGeneration,3);assert.equal(r.value.status(fresh,resourceRef).state,'UNLOCKED');assert.throws(()=>r.value.status(scope,resourceRef),exact('NOT_FOUND',404));}finally{r.value.dispose();}});
test('현재controlgeneration불일치관측은옛lease사용을차단하며새generation을묵시채택하지않는다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const old=open(r),current={...scope,controlGeneration:2};const view=r.value.status(current,resourceRef);assert.equal(view.state,'LOCKED');assert.equal(view.auditState,'UNKNOWN');assert.equal(view.leaseGeneration,2);assert(old.key.every(v=>v===0));const ticket=r.value.begin(current),key=Buffer.alloc(32,0x77);assert.throws(()=>r.value.activate(ticket,{resourceRef,expectedGeneration:1,key,deadline:r.now()+60000}),exact('RESOURCE_VERSION_CONFLICT',409));assert(key.every(v=>v===0));}finally{r.value.dispose();}});

test('status선조회없는새control activation도옛key/진행중ticket을차단하고재허가로오인하지않는다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const old=open(r),stale=r.value.begin(scope),current={...scope,controlGeneration:2},ticket=r.value.begin(current),nextKey=Buffer.alloc(32,0x88);assert.throws(()=>r.value.activate(ticket,{resourceRef,expectedGeneration:1,key:nextKey,deadline:r.now()+60000}),exact('RESOURCE_STATE_UNKNOWN',503));assert(old.key.every(v=>v===0));assert(nextKey.every(v=>v===0));const lateKey=Buffer.alloc(32,0x99);assert.throws(()=>r.value.activate(stale,{resourceRef,expectedGeneration:2,key:lateKey,deadline:r.now()+60000}),exact('RESOURCE_STATE_UNKNOWN',503));assert(lateKey.every(v=>v===0));assert.equal(r.value.status(current,resourceRef).state,'LOCKED');}finally{r.value.dispose();}});

test('원인증admit단발ticket은logout/만료뒤실패만기록하고위조·재사용은counter추가0이다',async()=>{const m=await api('store','InstallationResourceFailureLimiter'),f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access),ticket=await limiter.admit('t'.repeat(43),pid,keyId);assert(ticket&&typeof ticket==='object');f.authFail();f.advance(3600001);await assert.rejects(limiter.recordFailure({...ticket}),exact('RESOURCE_STATE_UNKNOWN',503));await limiter.recordFailure(ticket);assert.equal([...f.buckets.values()].find(v=>v.bucket_kind==='PROJECT')!.failures,1);await assert.rejects(limiter.recordFailure(ticket),exact('RESOURCE_STATE_UNKNOWN',503));assert.equal([...f.buckets.values()].find(v=>v.bucket_kind==='PROJECT')!.failures,1);assert.deepEqual(f.unexpected,[]);});
test('failures5·blockeduntilNULL불정합은한도미도달로취급하지않고KDF전503이다',async()=>{const m=await api('store','InstallationResourceFailureLimiter'),f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access);f.buckets.set('PROJECT:'+pid,{project_id:pid,bucket_kind:'PROJECT',bucket_key:pid,failures:5,window_started_at:new Date(f.now()),blocked_until:null});await assert.rejects(limiter.admit('t'.repeat(43),pid,keyId),exact('RESOURCE_STATE_UNKNOWN',503));assert(f.events.includes('READ_LIMIT'));assert.deepEqual(f.unexpected,[]);});
test('attempt기록DB불명/COMMIT전후유실은재시작RESERVED·RECORDED를보존해새KDF를막는다',async()=>{const m=await api('store','InstallationResourceFailureLimiter');for(const failure of ['storage','before','after'] as const){const f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access),ticket=await limiter.admit('t'.repeat(43),pid,keyId);if(failure==='storage')f.storageFail();else f.loseCommit(failure);await assert.rejects(limiter.recordFailure(ticket),exact('RESOURCE_STATE_UNKNOWN',503));f.storageRecover();const restarted=new m.InstallationResourceFailureLimiter(f.access);await assert.rejects(restarted.admit('t'.repeat(43),pid,keyId),exact('RESOURCE_STATE_UNKNOWN',503));assert([...f.attempts.values()].some(v=>['RESERVED','RECORDED'].includes(v.state)));assert.deepEqual(f.unexpected,[]);}});
test('성공attempt명시완결은다음admit를열지만이전실패counter를초기화하지않는다',async()=>{const m=await api('store','InstallationResourceFailureLimiter'),f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access);await limiter.recordFailure(await limiter.admit('t'.repeat(43),pid,keyId));const next=await limiter.admit('t'.repeat(43),pid,keyId);await limiter.completeSuccess(next);assert.equal([...f.buckets.values()].find(v=>v.bucket_kind==='PROJECT')!.failures,1);assert([...f.attempts.values()].some(v=>v.state==='SUCCEEDED'));assert(await limiter.admit('t'.repeat(43),pid,keyId));});

test('admit예약COMMIT확정rollback과commit뒤응답유실은ticket0/KDF0·영속효과를구분한다',async()=>{const m=await api('store','InstallationResourceFailureLimiter');for(const point of ['before','after'] as const){const f=counterFixture(),limiter=new m.InstallationResourceFailureLimiter(f.access);f.loseAdmitCommit(point);let ticket:unknown,kdfCalls=0;await assert.rejects((async()=>{ticket=await limiter.admit('t'.repeat(43),pid,keyId);kdfCalls++;})(),exact('RESOURCE_STATE_UNKNOWN',503));assert.equal(ticket,undefined);assert.equal(kdfCalls,0);const restarted=new m.InstallationResourceFailureLimiter(f.access);if(point==='before'){assert.equal(f.attempts.size,0);assert(await restarted.admit('t'.repeat(43),pid,keyId));}else{assert.equal(f.attempts.size,1);assert.equal([...f.attempts.values()][0].state,'RESERVED');await assert.rejects(restarted.admit('t'.repeat(43),pid,keyId),exact('RESOURCE_STATE_UNKNOWN',503));}assert.deepEqual(f.unexpected,[]);}});

test('로그아웃뒤새유효session은잠긴exactref의generation을조회해명시UNLOCK준비에쓴다',async()=>{const m=await api('store','InstallationKeyLeaseRegistry'),r=registry(m.InstallationKeyLeaseRegistry);try{const old=open(r);r.value.invalidateSession(sessionId);const fresh={...scope,sessionId:'99999999-9999-4999-8999-999999999999'},view=r.value.status(fresh,resourceRef);assert.equal(view.state,'LOCKED');assert.equal(view.leaseGeneration,2);assert(old.key.every(v=>v===0));assert(!Object.values(view).some(Buffer.isBuffer));const key=Buffer.alloc(32,0x66),ticket=r.value.begin(fresh);assert.equal(r.value.activate(ticket,{resourceRef,expectedGeneration:view.leaseGeneration,key,deadline:r.now()+60000}).leaseGeneration,3);assert.throws(()=>r.value.status(scope,resourceRef),exact('NOT_FOUND',404));}finally{r.value.dispose();}});

