test('targetReference 등록descriptor의정확ref만기존R2 TARGET명시저장에소비하고receipt/원승인귀속을보존한다',async()=>{const f=await intentFixture({withTargetReference:true});try{const intentRef=intentOk(await f.post(f.command)).data.intentRef,done=targetView(await targetPost(f,intentRef),intentRef,'SUCCEEDED'),snapshot={kind:'TARGET',displayName:'명시 선택한 설치 대상',spec:{installationResourceRef:done.resultRef},reason:'현재 보호조회 뒤 명시 등록'};const command={schemaVersion:1,projectId:pid,commandId:intentId(100),clientId,controlGeneration:1,operation:'saveBackupReference',targetId:null,expectedVersion:0,baselineRefs:[],approvalRef:null,payload:snapshot};const stored=await f.post(command);assert.equal(stored.statusCode,200,stored.body);const result=stored.json();assert.equal(result.data.status,'REFERENCE_STORED');const fixed=await targetGet(f,'/backup-references/'+result.data.ref.id+'/versions/1');assert.equal(fixed.statusCode,200,fixed.body);assert.deepEqual(fixed.json().snapshot,snapshot);assert.equal(fixed.json().current.eligible,true);assert.deepEqual(fixed.json().current.reasonCodes,[]);assert.equal(f.tables.commands.length,2);assert.equal(f.tables.receipts.length,2);assert.equal(f.tables.audits.length,2);assert.equal(f.tables.consumptions.length,1,'TARGET참조AUTO는원manage승인재소비0');assert.equal(f.references.versions.length,1);const body=f.tables.commands.find(c=>c.command_id===command.commandId);assert.equal(body.request_hash,intentHash(command));assert.equal(body.approval_consumption_id,null);assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetRace claim COMMIT완료와반환사이같은storeGET은PROCESSING을coldUNKNOWN으로오인하지않는다',async()=>{const f=await intentFixture();let release:(()=>void)|undefined;try{const ref=intentOk(await f.post(f.command)).data.intentRef,original=f.access.authenticated;let entered!:()=>void;const ready=new Promise<void>(r=>entered=r);let armed=true;f.access.authenticated=async(...args:any[])=>{const out=await original(...args);if(armed&&f.tables.intents[0]?.state==='PROCESSING'){armed=false;entered();await new Promise<void>(r=>release=r);}return out;};const pending=targetPost(f,ref);const race=await Promise.race([ready.then(()=>true),Promise.resolve(pending).then(()=>false)]);assert.equal(race,true);assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,0,'claim COMMIT반환확인전I/O0');targetView(await targetGet(f,'/backup-resource-intents/'+ref.id),ref,'PROCESSING');release!();targetView(await pending,ref,'SUCCEEDED');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.deepEqual(f.unexpected,[]);}finally{release?.();await f.close();}});
