function relockLifecycle(x:Awaited<ReturnType<typeof keyLifecycleFixture>>,generation:number){return x.f.app.inject({method:'POST',url:'/api/v1/projects/'+pid+'/backup-resources/'+x.keyRef.id+'/versions/'+x.keyRef.version+'/relock',headers:{host:'localhost:3830',cookie:'__Host-anvil.sid='+intentToken,origin:intentOrigin,'content-type':'application/json','x-anvil-csrf':intentCsrf},payload:{resourceRef:x.keyRef,expectedLeaseGeneration:generation}});}

// VERIFY/UNLOCK/RELOCK은 준비 명령의 승인만 한 번 소비한다. 아래 Secret 양성은 in-memory 서비스 경계이며 실TLS가 아니다.
test('keyLife VERIFY는새원승인1회만소비해copymetadata만확인하고원ENROLL/wrapping·LOCKED를보존한다',async()=>{const z=await keyLifecycleFixture();try{const original=structuredClone({command:z.f.tables.commands[0],receipt:z.f.tables.receipts[0],audit:z.f.tables.audits[0],version:z.f.resources.versions[0],wrapping:z.f.keys.wrappings[0]}),{a,ref}=await verifyLifecycleKey(z);assert.equal(z.f.tables.consumptions.length,2);assert.equal(z.f.tables.commands.length,2);assert.equal(z.f.tables.audits.length,2);assert.equal(z.unwraps(),1);assert(z.plain[0]!.every(v=>v===0),'VERIFY평문은lease로채택하지않고소거');const state=await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.copyConfirmed,true);assert.equal(state.state,'LOCKED');assert.equal(state.leaseGeneration,0);assert.equal(z.r.value.status(scope,z.keyRef).state,'LOCKED');assert.equal(z.f.keys.wrappings.length,1);assert.deepEqual({command:z.f.tables.commands[0],receipt:z.f.tables.receipts[0],audit:z.f.tables.audits[0],version:z.f.resources.versions[0],wrapping:z.f.keys.wrappings[0]},original);const before={unwraps:z.unwraps(),consumes:z.f.tables.consumptions.length,events:z.f.keys.events.length};await z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}});assert.deepEqual({unwraps:z.unwraps(),consumes:z.f.tables.consumptions.length,events:z.f.keys.events.length},before);assert.equal(a.source.status,'CONSUMED');const select={schemaVersion:1,projectId:pid,commandId:intentId(1190),clientId,controlGeneration:1,operation:'saveBackupReference',targetId:null,expectedVersion:0,baselineRefs:[],approvalRef:null,payload:{kind:'ENCRYPTION_KEY',displayName:'보관확인한키',spec:{installationResourceRef:z.keyRef},reason:'실확인뒤명시선택'}};const saved=await z.f.post(select);assert.equal(saved.statusCode,200,saved.body);assert.equal(saved.json().data.status,'REFERENCE_STORED');assert.equal(z.f.tables.consumptions.length,2,'참조AUTO는키승인재소비0');assertNoEnrollmentLeaks(z.x,saved.json());assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});
test('keyLife UNLOCK→본인RELOCK은같은lease generation을닫고OWNER/control상실도사용차단을막지않는다',async()=>{const z=await keyLifecycleFixture();try{const u=await unlockLifecycleKey(z);assert.equal(u.state.state,'UNLOCKED');assert.equal(u.state.copyConfirmed,true);assert.equal(u.state.leaseGeneration,1);assert.equal(z.f.tables.consumptions.length,3);assert.equal(z.plain.length,2);assert(z.plain[0]!.every(v=>v===0));assert(z.plain[1]!.some(v=>v!==0));assert(Date.parse(u.state.unlockedUntil)<=z.r.now()+300000);assert(!Object.values(u.state).some(Buffer.isBuffer));z.f.current.participation='VIEWER';z.f.current.control=false;const closed=await relockLifecycle(z,1);assert.equal(closed.statusCode,200,closed.body);assert.equal(closed.json().state,'LOCKED');assert.equal(closed.json().leaseGeneration,2);assert.equal(closed.json().auditState,'RECORDED');assert(z.plain[1]!.every(v=>v===0));assert.equal(z.f.tables.consumptions.length,3);assert.equal(z.f.tables.commands.length,3);assert.equal(z.f.tables.audits.length,3);assertNoEnrollmentLeaks(z.x,closed.json());assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});
test('keyLife RELOCK기록실패는memory key먼저소거하고LOCKED/auditUNKNOWN·generation을보존한다',async()=>{const z=await keyLifecycleFixture();try{const u=await unlockLifecycleKey(z,1400);u.a.port.failState=true;u.a.port.onStateWrite=()=>{assert(z.plain.at(-1)!.every(v=>v===0),'DB기록전사용차단');};const result=await relockLifecycle(z,u.state.leaseGeneration);assert.equal(result.statusCode,200,result.body);assert.equal(result.json().state,'LOCKED');assert.equal(result.json().auditState,'UNKNOWN');assert.equal(result.json().leaseGeneration,2);assert.equal(u.a.port.stateFaults,1);assert(z.plain.at(-1)!.every(v=>v===0));u.a.port.failState=false;const queried=await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(queried.state,'LOCKED');assert.equal(queried.leaseGeneration,2);assert.equal(queried.auditState,'UNKNOWN');assert.equal(z.f.tables.consumptions.length,3);assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});
test('keyLife staleRELOCK/옛UNLOCK성공재조회는더새lease를닫거나재해제하지않는다',async()=>{const z=await keyLifecycleFixture();try{const first=await unlockLifecycleKey(z,1600);assert.equal((await relockLifecycle(z,1)).statusCode,200);const before=z.unwraps();await z.store.fulfill(intentToken,intentCsrf,pid,first.ref.id,{intentRef:first.ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}});let state=await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.state,'LOCKED');assert.equal(state.leaseGeneration,2);assert.equal(z.unwraps(),before);const a=lifecycleApproval(z.x,'UNLOCK_KEY',z.keyRef,z.hash,1700,2),ref=await lifecycleIntent(z,a);await z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}});state=await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.state,'UNLOCKED');assert.equal(state.leaseGeneration,3);const active=z.plain.at(-1)!;intentError(await relockLifecycle(z,1),409,'RESOURCE_VERSION_CONFLICT');assert(active.some(v=>v!==0));assert.equal((await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version)).leaseGeneration,3);assert.equal(z.f.tables.consumptions.length,4);assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});
test('keyLife UNLOCK오류비밀번호는실GCM검증실패통합422·독립양counter1·평문사용0이다',async()=>{const z=await keyLifecycleFixture();try{await verifyLifecycleKey(z,1800);const a=lifecycleApproval(z.x,'UNLOCK_KEY',z.keyRef,z.hash,1900,0),ref=await lifecycleIntent(z,a),before=Buffer.from([...z.f.vault!.files.values()][0].bytes);await assert.rejects(z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:'synthetic-public-wrong-passphrase-2026',envelope:z.wire}}),exact('KEY_UNLOCK_FAILED',422));assert.equal(z.f.keys.limits.length,2);assert(z.f.keys.limits.every((v:any)=>v.failures===1));assert(z.f.keys.attempts.some((v:any)=>v.origin_intent_id===ref.id&&v.state==='FAILED'));assert(z.plain.every(key=>key.every(v=>v===0)));assert.equal((await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version)).state,'LOCKED');assert.deepEqual([...z.f.vault!.files.values()][0].bytes,before);assert.equal(z.f.tables.consumptions.length,3);assertNoEnrollmentLeaks(z.x,null);assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});
test('keyLife KDF중제어회수는원ticket늦은activation/평문채택을막고소거한다',async()=>{const z=await keyLifecycleFixture();try{await verifyLifecycleKey(z,2000);const a=lifecycleApproval(z.x,'UNLOCK_KEY',z.keyRef,z.hash,2100,0),ref=await lifecycleIntent(z,a);let entered!:()=>void;const ready=new Promise<void>(r=>entered=r);z.kdf.entered=entered;z.kdf.pause=true;const run=z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}}),reached=await Promise.race([ready.then(()=>true),run.then(()=>false,()=>false)]);assert.equal(reached,true,'실KDF진입관측');z.f.current.generation=2;z.kdf.release!();await assert.rejects(run,exact('CONTROL_GENERATION_CONFLICT',409));assert(z.plain.every(key=>key.every(v=>v===0)));assert.equal(z.r.value.status(scope,z.keyRef).state,'LOCKED');assert.equal(z.f.tables.consumptions.length,3);assert.deepEqual(z.f.unexpected,[]);}finally{z.kdf.release?.();await z.close();}});
