test('keyLifeBoundary timer만료는DB감사와무관하게즉시소거하고다음세대만새승인으로연다',async()=>{const z=await keyLifecycleFixture();try{const first=await unlockLifecycleKey(z,2400);z.advance(Date.parse(first.state.unlockedUntil)-z.r.now());assert(z.plain.at(-1)!.every(v=>v===0));const state=await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.state,'LOCKED');assert.equal(state.leaseGeneration,2);assert.equal(state.auditState,'UNKNOWN');assert.equal(z.r.timers.size,0);}finally{await z.close();}});
test('keyLifeBoundary 재시작은저장UNLOCKED를복원하지않고고정세대전진후새승인만허용한다',async()=>{const z=await keyLifecycleFixture();let next:any;try{const first=await unlockLifecycleKey(z,2600);z.store.dispose();assert(z.plain.at(-1)!.every(v=>v===0));const m=await api('store','InstallationResourceStore','InstallationKeyLeaseRegistry');const fresh=registry(m.InstallationKeyLeaseRegistry);fresh.advance(z.r.now()-fresh.now());next=new m.InstallationResourceStore(z.f.access,{catalog:z.f.access.installationResourceCatalog,registry:fresh.value});const state=await next.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.state,'LOCKED');assert.equal(state.leaseGeneration,first.state.leaseGeneration+1);assert.equal(state.auditState,'UNKNOWN');assert.equal(fresh.timers.size,0);const replay=await next.fulfill(intentToken,intentCsrf,pid,first.ref.id,{intentRef:first.ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}});assert.equal(replay.state,'SUCCEEDED');assert.equal((await next.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version)).state,'LOCKED');}finally{next?.dispose();await z.close();}});
test('keyLifeBoundary relockCOMMIT응답유실은소거를유지하고RECORDED를주장하지않는다',async()=>{const z=await keyLifecycleFixture();try{const u=await unlockLifecycleKey(z,2800),original=z.f.access.authenticated;z.f.access.authenticated=async(token:string,csrf:string|null,body:Function)=>{const result=await original(token,csrf,body);if(result?.state==='LOCKED')throw Error('synthetic-relock-commit-lost');return result;};const closed=await relockLifecycle(z,u.state.leaseGeneration);assert.equal(closed.statusCode,200,closed.body);assert.equal(closed.json().state,'LOCKED');assert.equal(closed.json().auditState,'UNKNOWN');assert(z.plain.at(-1)!.every(v=>v===0));}finally{await z.close();}});
test('keyLifeAuth logout은실repository의검증된자기session키를DB쓰기전에폐기한다',async()=>{const {createHash}=await import('node:crypto'),{AccessRepository}=await import('../../../apps/server/modules/access/repository.ts'),m=await api('store','InstallationKeyLeaseRegistry');for(const wrong of [false,true]){const r=registry(m.InstallationKeyLeaseRegistry),opened=open(r);let writes=0;const pool:any={connect:async()=>({release(){},query:async(sql:string,args:any[])=>{if(sql==='BEGIN'||sql==='ROLLBACK'||sql==='COMMIT')return{rows:[]};if(sql.startsWith('SELECT id,csrf_digest,revoked_at'))return{rows:[{id:sessionId,csrf_digest:createHash('sha256').update('csrf').digest('hex'),revoked_at:null}]};if(sql.startsWith('UPDATE anvil.auth_sessions')){writes++;assert(opened.key.every(v=>v===0),'실DB쓰기전메모리폐기');throw Error('synthetic-write-failed');}throw Error('unexpected-auth-sql:'+sql);}})};const repo=new AccessRepository(pool,{installationId:pid,key:Buffer.alloc(32,1)});repo.installationKeyRegistry=r.value;try{await assert.rejects(repo.logout('a'.repeat(43),wrong?'wrong':'csrf'));assert.equal(writes,wrong?0:1);assert.equal(r.value.status(scope,resourceRef).state,wrong?'UNLOCKED':'LOCKED');}finally{r.value.dispose();}}});

test('keyLifeBoundary 최종metadata저장뒤activation거절은FAILED대신UNKNOWN보존',async()=>{const z=await keyLifecycleFixture();try{const a=lifecycleApproval(z.x,'VERIFY_KEY_COPY',z.keyRef,z.hash,3000),ref=await lifecycleIntent(z,a),original=z.f.access.authenticated;let once=true;z.f.access.authenticated=async(token:string,csrf:string|null,body:Function)=>{const result=await original(token,csrf,body);if(once&&result?.state==='SUCCEEDED'){once=false;throw new AuthFailure('RESOURCE_UNVERIFIED',412);}return result;};await assert.rejects(z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}}),exact('RESOURCE_UNVERIFIED',412));const state=await z.store.readIntent(intentToken,pid,ref.id);assert.equal(state.state,'UNKNOWN');assert(z.plain.every(key=>key.every(v=>v===0)));assert.equal(z.f.keys.states[0].copy_confirmed,true,'저장된metadata는보존');assert.equal(z.f.tables.consumptions.length,2);}finally{await z.close();}});

test('keyLifeBoundary keyState최종COMMIT중회수는과거UNLOCKED를새조회로반환하지않는다',async()=>{const z=await keyLifecycleFixture();try{await unlockLifecycleKey(z,3200);const original=z.f.access.authenticated;let once=true;z.f.access.authenticated=async(token:string,csrf:string|null,body:Function)=>{const result=await original(token,csrf,body);if(once&&result?.copyConfirmed===true){once=false;z.r.value.invalidateSession(sessionId);}return result;};const state=await z.store.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.state,'LOCKED');assert.equal(state.leaseGeneration,2);assert.equal(state.auditState,'UNKNOWN');assert(z.plain.at(-1)!.every(v=>v===0));}finally{await z.close();}});

test('keyLifeBoundary 재시작freshApp은고정LOCKED세대새승인으로실제다시해제한다',async()=>{const z=await keyLifecycleFixture();let next:any,app:any;try{const first=await unlockLifecycleKey(z,3400);await z.f.app.close();z.store.dispose();const m=await api('store','InstallationResourceStore','InstallationKeyLeaseRegistry'),fresh=registry(m.InstallationKeyLeaseRegistry);fresh.advance(z.r.now()-fresh.now());next=new m.InstallationResourceStore(z.f.access,{catalog:z.f.access.installationResourceCatalog,registry:fresh.value,crypto:z.crypto});assert.equal(z.f.access.installationKeyRegistry,fresh.value);app=buildApp({},undefined,{repository:z.f.access,origin:intentOrigin});const state=await next.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(state.leaseGeneration,2);assert.equal(state.state,'LOCKED');const a=lifecycleApproval(z.x,'UNLOCK_KEY',z.keyRef,z.hash,3500,2),response=await app.inject({method:'POST',url:'/api/v1/projects/'+pid+'/commands',headers:{host:'localhost:3830',cookie:'__Host-anvil.sid='+intentToken,origin:intentOrigin,'x-anvil-csrf':intentCsrf},payload:a.command});assert.equal(response.statusCode,200,response.body);const ref=response.json().data.intentRef;await next.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:z.wire}});const after=await next.keyState(intentToken,pid,z.keyRef.id,z.keyRef.version);assert.equal(after.state,'UNLOCKED');assert.equal(after.leaseGeneration,3);assert(z.plain.at(-1)!.some(v=>v!==0));assert.equal(z.f.tables.consumptions.length,4);assert.deepEqual(z.f.unexpected,[]);}finally{next?.dispose();await app?.close();await z.close();}});

// Two independently enrolled/verified public fixtures share one project registry; no real DB or keys.
async function twoKeyLifecycle(mode:'ACTIVE'|'COLD'|'REVOKED'){
 const a=await keyLifecycleFixture(),b=await keyLifecycleFixture();let next:any,app:any;
 try{await unlockLifecycleKey(a,3700);await verifyLifecycleKey(b,3900);const stale=structuredClone(a.f.keys.states[0]);b.f.keys.states.push(stale);const descriptor=structuredClone(a.f.resources.versions[0]);b.f.resources.versions.push(descriptor);await b.f.app.close();b.store.dispose();
 const m=await api('store','InstallationResourceStore','InstallationKeyLeaseRegistry');let shared=a.r.value;
 if(mode==='COLD'){a.store.dispose();const fresh=registry(m.InstallationKeyLeaseRegistry);fresh.advance(a.r.now()-fresh.now());shared=fresh.value;}
 if(mode==='REVOKED')a.r.value.invalidateSession(sessionId);
 const observed={reductions:0,guardHits:0};
 const instrument=()=>{const original=b.f.access.authenticated;b.f.access.authenticated=async(token:string,csrf:string|null,body:Function)=>original(token,csrf,(db:any,actor:any)=>body({query:async(sql:string,args:any[]=[])=>{
 const q=sql.replace(/\s+/g,' ').trim();
 if(q.startsWith("SELECT set_config('anvil.installation_reconcile_intent'"))return{rows:[]};
 if(q.startsWith('SELECT k.*,v.content_hash FROM anvil.installation_key_states'))return{rows:b.f.keys.states.filter((r:any)=>r.project_id===args[0]&&r.resource_id!==args[1]&&r.state==='UNLOCKED').map((r:any)=>({...structuredClone(r),content_hash:b.f.resources.versions.find((v:any)=>v.resource_id===r.resource_id)!.content_hash}))};
 if(q.startsWith('UPDATE anvil.installation_key_states SET ')){
  const stateSet=/state=\$(\d+)/.exec(q),target=args[1];
  if(stateSet&&args[Number(stateSet[1])-1]==='UNLOCKED'&&b.f.keys.states.some((r:any)=>r.resource_id!==target&&r.state==='UNLOCKED'&&r.unlocked_until>new Date(b.f.at))){observed.guardHits++;throw Error('INSTALLATION_ONE_PROJECT_LEASE');}
  if(target===a.keyRef.id&&stateSet&&args[Number(stateSet[1])-1]==='LOCKED')observed.reductions++;
 }
 return db.query(sql,args);
 }},actor));};
 next=new m.InstallationResourceStore(b.f.access,{catalog:b.f.access.installationResourceCatalog,registry:shared,crypto:b.crypto});app=buildApp({},undefined,{repository:b.f.access,origin:intentOrigin});b.f.post=(c:any)=>app.inject({method:'POST',url:'/api/v1/projects/'+pid+'/commands',headers:{host:'localhost:3830',cookie:'__Host-anvil.sid='+intentToken,origin:intentOrigin,'x-anvil-csrf':intentCsrf},payload:c});
 return{a,b,store:next,shared,observed,instrument,async close(){next.dispose();await app.close();await a.close();await b.close();}};
 }catch(e){next?.dispose();await app?.close();await a.close();await b.close();throw e;}
}
for(const mode of ['ACTIVE','COLD','REVOKED'] as const)test('keyLifeTwo '+mode+' 다른키는현재평문소유와과거DB관측을구분한다',async()=>{const z=await twoKeyLifecycle(mode);try{const x=z.b,approval=lifecycleApproval(x.x,'UNLOCK_KEY',x.keyRef,x.hash,4100,0),ref=await lifecycleIntent(x,approval);z.instrument();const run=z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:x.wire}});
 if(mode==='ACTIVE'){await assert.rejects(run,exact('RESOURCE_LIMIT',429));assert.equal(z.observed.reductions,0);assert.equal(z.observed.guardHits,0,'메모리소유선검사');assert(z.a.plain.at(-1)!.some(v=>v!==0));assert.equal(z.a.r.value.status(scope,z.a.keyRef).state,'UNLOCKED');}
 else{assert.equal((await run).state,'SUCCEEDED');assert.equal(z.observed.reductions,1);assert.equal(z.observed.guardHits,0);const old=x.f.keys.states.find((r:any)=>r.resource_id===z.a.keyRef.id)!;assert.equal(old.state,'LOCKED');assert.equal(old.lease_generation,2);assert.equal(old.unlocked_until,null);assert(z.a.plain.at(-1)!.every(v=>v===0));assert.equal((await z.store.keyState(intentToken,pid,x.keyRef.id,1)).state,'UNLOCKED');assert(x.plain.at(-1)!.some(v=>v!==0));}
 assert.equal(x.f.tables.consumptions.length,3,'원승인재소비없음');assert.deepEqual(x.f.unexpected,[]);
 }finally{await z.close();}});

