test('importKey publish뒤DB불명은원파일보존UNKNOWN이며자동재시도0',async()=>{const z=await importFixture();try{const ref=await z.start();z.f.vault!.state.afterParent=()=>{z.f.fault.mode='WRAPPING';};await assert.rejects(imported(z,ref),exact('RESOURCE_STATE_UNKNOWN',503));assert.equal(z.f.fault.hits,1);assert.equal(z.f.vault!.files.size,1);assert.equal(z.f.tables.intents[0].state,'UNKNOWN');assert.equal(z.f.resources.versions.length,0);const calls=z.unwraps(),writes=z.f.vault!.trace.length;z.f.fault.mode='';await assert.rejects(imported(z,ref),exact('RESOURCE_STATE_UNKNOWN',503));assert.equal(z.unwraps(),calls);assert.equal(z.f.vault!.trace.length,writes);assert(z.plain.every(v=>v.every(b=>b===0)));}finally{await z.close();}});
test('importKey 원명령replay및동일keytuple재가져오기는추가descriptor0',async()=>{const z=await importFixture();try{const ref=await z.start(),first=await imported(z,ref),calls=z.unwraps(),files=z.f.vault!.files.size;const replay=await z.f.post(z.approval.command);assert.equal(replay.statusCode,200,replay.body);assert.deepEqual(replay.json().data.intentRef,ref);assert.deepEqual(await imported(z,ref),first);assert.equal(z.unwraps(),calls);assert.equal(z.f.tables.consumptions.length,1);const a=importApproval(z.x,z.hash,6400),second=await z.f.post(a.command);assert.equal(second.statusCode,200,second.body);const next=second.json().data.intentRef;await assert.rejects(imported(z,next),exact('RESOURCE_VERSION_CONFLICT',409));assert.equal(z.f.resources.versions.length,1);assert.equal(z.f.vault!.files.size,files);assert.equal(z.unwraps(),calls);assert.equal(z.f.tables.consumptions.length,2);assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});

test('importKeyFirstSubmission 틀린hash첫제출후같은intent정상암호문재실행0',async()=>{const z=await importFixture();try{const ref=await z.start(),wrong=JSON.parse(z.wire);wrong.createdAt='2025-01-02T00:00:00.000Z';await assert.rejects(z.store.fulfill(intentToken,intentCsrf,pid,ref.id,{intentRef:ref,secretInput:{passphrase:enrollmentPassword,envelope:browserCanonicalForImport(wrong)}}),exact('RESOURCE_VERSION_CONFLICT',409));assert.equal(z.unwraps(),0);assert.equal(z.f.vault!.files.size,0);assert.equal(z.f.tables.intents[0].state,'FAILED','유효원귀속의첫제출은실패해도소비');await assert.rejects(imported(z,ref),exact('RESOURCE_UNVERIFIED',412));assert.equal(z.unwraps(),0);assert.equal(z.f.vault!.files.size,0);assert.equal(z.f.resources.versions.length,0);assert.equal(z.f.tables.consumptions.length,1);assert.deepEqual(z.f.unexpected,[]);}finally{await z.close();}});
